-- 2026-09-30 · Q100 — Ciclo 2 completo (187 tareas finales) desde la auditoría
-- Fuente autoritativa: catalogo_acciones.csv (Q100_Auditoria). Área = responsable_visible.
-- Antes: 40/187 avances C2. Ahora: 187 (promedio 85,877% -> 86%, 85 críticas, 2 críticas <30).
-- No toca el Ciclo 3 (ya correcto). Datos de semilla; sin avances reales de usuarios aún.

-- Ciclo 2 completo (187 tareas) desde catalogo_acciones.csv (auditoría).
-- Borra los 40 avances C2 parciales previos y carga el set completo.
delete from q100.avances where ciclo_id='c2026q2';

on conflict (linea_id) do nothing;

on conflict (accion_id) do update set linea_id=excluded.linea_id,meta_id=excluded.meta_id,area_id=excluded.area_id,accion=excluded.accion,origen=excluded.origen,criticidad=excluded.criticidad,fecha_termino=excluded.fecha_termino;

